use super::*;

/// `g` without the records [`reconcile_seed`] appended to it — the ones `main` must not adopt.
///
/// [`load`] returns the ledger's `main` OVERLAID with the packaged seed, because the app needs both:
/// the crate modules live in the ledger and the frontend population ships in the seed. `save` then
/// hands that combined document to `sync_document`, which makes `main` EQUAL to it — so a single
/// `impl set` quietly promoted the whole seed onto `main`.
///
/// MEASURED on this machine: `main`'s `.ts` population went from 79 to 698 in one burst of 742
/// note-less revisions. `main` is what the export writes into `graph/records/`, so the next export
/// would have added ~619 frontend records to the committed store — the same union the import was
/// rewritten to stop making, arriving through the other door.
///
/// A record is a reconcile artifact when `main` does not have it AND it is byte-identical to the
/// seed's copy. Anything a librarian actually edited differs from the seed by construction, so it is
/// kept and lands on `main` as it should.
pub(crate) fn without_seed_reconcile(db: &bsc_graph_store::Connection, g: &Value) -> Result<Value, String> {
    let seeded: std::collections::BTreeMap<String, Value> = implementations_of(&seed())
        .into_iter()
        .filter_map(|im| im.get("id").and_then(Value::as_str).map(|id| (id.to_string(), im.clone())))
        .collect();
    let mut out = g.clone();
    if let Some(arr) = out.get_mut("implementations").and_then(Value::as_array_mut) {
        let mut kept: Vec<Value> = Vec::with_capacity(arr.len());
        for im in arr.drain(..) {
            let id = im.get("id").and_then(Value::as_str).unwrap_or_default().to_string();
            let is_artifact = !id.is_empty()
                && bsc_graph_store::get_in(db, &bound_lane(), &id)?.is_none()
                && bsc_graph_store::get(db, &id)?.is_none()
                && seeded.get(&id).is_some_and(|s| {
                    bsc_graph_store::import::body_of(s) == bsc_graph_store::import::body_of(&im)
                });
            if !is_artifact {
                kept.push(im);
            }
        }
        *arr = kept;
    }
    Ok(out)
}
